#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static char *ibuf;
static size_t ipos = 0, ilen = 0;

static int readInt(void) {
    while (ipos < ilen && (ibuf[ipos] < '0' || ibuf[ipos] > '9')) ipos++;
    int x = 0;
    while (ipos < ilen && ibuf[ipos] >= '0' && ibuf[ipos] <= '9')
        x = x * 10 + (ibuf[ipos++] - '0');
    return x;
}

static int *head_, *nxt_, *to_, *dist_, *par_, *que_;
static int ecnt;

static void addEdge(int a, int b) {
    ecnt++; to_[ecnt] = b; nxt_[ecnt] = head_[a]; head_[a] = ecnt;
    ecnt++; to_[ecnt] = a; nxt_[ecnt] = head_[b]; head_[b] = ecnt;
}

static int bfs(int s, int n) {
    for (int i = 1; i <= n; i++) { dist_[i] = -1; par_[i] = 0; }
    int qh = 0, qt = 0, far = s;
    que_[qt++] = s; dist_[s] = 0;
    while (qh < qt) {
        int u = que_[qh++];
        if (dist_[u] > dist_[far]) far = u;
        for (int e = head_[u]; e; e = nxt_[e]) {
            int v = to_[e];
            if (dist_[v] < 0) {
                dist_[v] = dist_[u] + 1;
                par_[v] = u;
                que_[qt++] = v;
            }
        }
    }
    return far;
}

/* centro de uma arvore: no que minimiza a excentricidade (raio = ceil(D/2)) */
static int centerOf(int n, int start) {
    int u = bfs(start, n);
    int v = bfs(u, n);          /* v extremo do diametro */
    int L = dist_[v];           /* diametro em arestas */
    int steps = L - L / 2;      /* ceil(L/2) passos de volta de v */
    int c = v;
    while (steps--) c = par_[c];
    return c;
}

int main(void) {
    size_t cap = 1 << 20, r;
    ibuf = (char *)malloc(cap);
    ilen = 0;
    while ((r = fread(ibuf + ilen, 1, cap - ilen, stdin)) > 0) {
        ilen += r;
        if (ilen == cap) {
            cap <<= 1;
            ibuf = (char *)realloc(ibuf, cap);
        }
    }

    int N = readInt();
    int M = readInt();
    int mx = N > M ? N : M;

    head_ = (int *)calloc((size_t)mx + 2, sizeof(int));
    dist_ = (int *)malloc(((size_t)mx + 2) * sizeof(int));
    par_  = (int *)malloc(((size_t)mx + 2) * sizeof(int));
    que_  = (int *)malloc(((size_t)mx + 2) * sizeof(int));
    nxt_  = (int *)malloc(((size_t)mx + 2) * 2 * sizeof(int));
    to_   = (int *)malloc(((size_t)mx + 2) * 2 * sizeof(int));

    /* sistema Circulo */
    ecnt = 0;
    for (int i = 0; i < N - 1; i++) {
        int a = readInt(), b = readInt();
        addEdge(a, b);
    }
    int c1 = centerOf(N, 1);

    /* sistema Quadrado */
    memset(head_, 0, ((size_t)mx + 2) * sizeof(int));
    ecnt = 0;
    for (int i = 0; i < M - 1; i++) {
        int a = readInt(), b = readInt();
        addEdge(a, b);
    }
    int c2 = centerOf(M, 1);

    printf("%d %d\n", c1, c2);
    return 0;
}
